import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from '../types';

const ChatAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Jambo! I am the Zamani Assistant. How can I help you with your furniture needs today?' }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSendMessage = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        })), { role: 'user', parts: [{ text: input }] }].slice(-10), // Context window
        config: {
          systemInstruction: `You are a helpful customer assistant for 'Zamani Crafts & Furniture', a premium Kenyan business. 
          Your goals:
          1. Answer questions about furniture, interior design, and materials (Mahogany, Acacia, etc.).
          2. Use Kenyan cultural nuances (e.g., greet with Jambo or Habari).
          3. Mention prices in KES if asked. Example prices: Mahogany Desk - KES 45,000, Accent Chairs - KES 32,000, Dining Table - KES 85,000.
          4. Encourage people to visit the showroom on Ngong Road, Nairobi.
          Keep responses concise and professional.`,
          temperature: 0.7,
        }
      });

      const modelText = response.text || "I'm sorry, I'm having trouble connecting right now. Please try again or call us!";
      setMessages(prev => [...prev, { role: 'model', text: modelText }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "Poleni sana, our system is currently undergoing maintenance. Please reach us via WhatsApp!" }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100]">
      {isOpen ? (
        <div className="bg-white rounded-2xl shadow-2xl w-[350px] sm:w-[400px] h-[500px] flex flex-col overflow-hidden border border-gray-100 animate-in fade-in zoom-in duration-300">
          {/* Header */}
          <div className="bg-black p-4 flex justify-between items-center text-white">
            <div className="flex items-center">
              <div className="w-8 h-8 bg-[#006600] rounded-full flex items-center justify-center mr-3">
                <i className="fa-solid fa-robot text-xs"></i>
              </div>
              <div>
                <h4 className="font-bold text-sm">Zamani Assistant</h4>
                <div className="flex items-center text-[10px] text-green-400">
                  <span className="w-1.5 h-1.5 bg-green-400 rounded-full mr-1"></span>
                  Online
                </div>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:text-[#BB0000] transition-colors">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 space-y-4 bg-gray-50">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                  m.role === 'user' 
                    ? 'bg-[#BB0000] text-white rounded-tr-none shadow-md' 
                    : 'bg-white text-gray-800 border border-gray-100 rounded-tl-none shadow-sm'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl border border-gray-100 shadow-sm flex space-x-1">
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-4 bg-white border-t border-gray-100">
            <div className="relative">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                placeholder="Ask us anything..."
                className="w-full pl-4 pr-12 py-3 bg-gray-50 border border-gray-200 rounded-full focus:outline-none focus:ring-1 focus:ring-[#006600] text-sm"
              />
              <button 
                onClick={handleSendMessage}
                disabled={isTyping}
                className="absolute right-2 top-1.5 w-9 h-9 bg-black text-white rounded-full flex items-center justify-center hover:bg-[#006600] disabled:bg-gray-300 transition-colors"
              >
                <i className="fa-solid fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-black hover:bg-[#BB0000] text-white w-14 h-14 rounded-full shadow-xl flex items-center justify-center transition-all transform hover:scale-110 active:scale-95 group"
        >
          <div className="absolute -top-1 -right-1 bg-[#006600] w-4 h-4 rounded-full border-2 border-white animate-pulse"></div>
          <i className="fa-solid fa-comment-dots text-xl"></i>
        </button>
      )}
    </div>
  );
};

